SELECT  FROM kb_document_tag t WHERE TRUE
AND t.enabled = #{enabled}

ORDER BY t.id LIMIT #{limit}


SELECT  FROM kb_document_tag t WHERE EXISTS (
    SELECT 1 FROM kb_document_tag_relation r JOIN kb_document d ON d.id = r.document_id
    WHERE r.tag_id = t.id AND d.status NOT IN ('deleted', 'archived') AND d.security_level <= #{clearance}
    AND 
    AND 
)

ORDER BY t.id LIMIT #{limit}
